// variant of https://shadertoy.com/view/4dGSWR

void mainImage( out vec4 O, vec2 u ){
    O = I(u);
}

#define T(v) texture(iChannel0, P+=v).w

void mainImage( out vec4 O, vec2 U )
{
    vec2 R = iResolution.xy,
         M = iMouse.xy,
         h=1./R, v=h, P=U*h; h.y = v.x = 0.;

    float n =  T(-v)+T(h)+T(v)+T(v)  +T(-h)  +T(-h)+T(-v)+T(-v) - 3.;   // count life in neighborhood

    O.w = float(   n*n==-T(h+v)*n                                       // 2 neighbors:survive 3:birth
                || abs( textureLod(iChannel1, U/R, 2.).r - .8 ) < .05   // video triggers cells
                || iMouse.z > .5 && length( M - U ) < 10.               // mouse paint
               );
    O.rgb = max( I(U).www, vec3(.98,.96,.94)* I(U).rgb);

}
